export interface WebPaymentsConfiguration extends WebNonvisualComponentOptions {
    readonly gatewaySlug?: string;
    readonly mode?: 'payment' | 'subscription';
    readonly enabled?: boolean;
    readonly pollInterval?: number;
    readonly pollTimeout?: number;
    readonly autoResume?: boolean;
    readonly autoWatch?: boolean;
    readonly persistAttempts?: boolean;
    /** Runtime-only durable adapter; never serialized into the Project Model. */
    readonly storage?: WebPaymentsStorageAdapter;
}

export interface WebPaymentsStorageAdapter {
    getItem(key: string): string | null;
    setItem(key: string, value: string): void;
    removeItem(key: string): void;
    withLock?<T>(name: string, action: () => Promise<T>, signal?: AbortSignal): Promise<T>;
}

/** Application-owned recovery data. Save before POST and again before navigation. */
export interface WebPaymentsCheckpoint {
    readonly version: 1;
    readonly baseUrl: string;
    readonly gatewaySlug: string;
    readonly userId: string;
    readonly sourceKey: string;
    readonly mode: 'payment' | 'subscription';
    readonly idempotencyKey: string;
    readonly operationId?: string;
}

export interface WebPaymentsObservationOptions {
    readonly signal?: AbortSignal;
    readonly interval?: number;
    readonly timeout?: number;
}

export interface WebPaymentsCheckoutOptions extends WebPaymentsObservationOptions {
    /** Defaults to true. False prepares an open checkout for custom authored UI. */
    readonly openCheckout?: boolean;
}

export interface WebPaymentsResumeOptions extends WebPaymentsObservationOptions {
    readonly mode?: 'payment' | 'subscription';
    /** Defaults to the component's autoWatch setting. Never opens checkout. */
    readonly watch?: boolean;
}

export interface WebPaymentsConfirmationOptions extends WebPaymentsObservationOptions {
    readonly operationId?: string;
    /** Financial confirmation is enough by default; source synchronization is separate. */
    readonly waitForSynchronization?: boolean;
}

export type WebPaymentsState = 'idle' | 'restoring' | 'preparing' | 'creating' | 'waiting' | 'opening' | 'watching' | 'refreshing' | 'loading-history' | 'canceling' | 'ready' | 'confirmed' | 'canceled' | 'uncertain' | 'failed' | 'error';

export interface WebPaymentsStateEventDetail {
    readonly previous: WebPaymentsState;
    readonly state: WebPaymentsState;
}

export interface WebPaymentsHistoryEventDetail {
    readonly items: readonly import("@webrad/restgo-sdk").RestGoPaymentOperation[];
    readonly nextCursor: string;
    readonly hasMore: boolean;
}

export interface WebPaymentsResumeEventDetail {
    readonly checkpoint: WebPaymentsCheckpoint;
    readonly operation: import("@webrad/restgo-sdk").RestGoPaymentOperation | null;
    readonly automatic: boolean;
}

export type WebPaymentsAction = 'pay' | 'subscribe' | 'checkout' | 'resume' | 'refresh' | 'history' | 'load-more' | 'confirm' | 'create' | 'get' | 'list' | 'cancel' | 'wait' | 'watch';

export interface WebPaymentsOperationEventDetail {
    readonly previous: import("@webrad/restgo-sdk").RestGoPaymentOperation | null;
    readonly operation: import("@webrad/restgo-sdk").RestGoPaymentOperation | null;
}

export interface WebPaymentsCheckoutEventDetail {
    readonly operation: import("@webrad/restgo-sdk").RestGoPaymentOperation;
}

export interface WebPaymentsSynchronizationEventDetail {
    readonly operation: import("@webrad/restgo-sdk").RestGoPaymentOperation;
    readonly pending: boolean;
    readonly error: string | null;
}

export interface WebPaymentsErrorEventDetail {
    readonly action: WebPaymentsAction;
    readonly operationId: string | null;
    readonly error: Error;
}

export interface WebPaymentsRequestEventDetail {
    readonly action: WebPaymentsAction;
    readonly operationId: string | null;
    readonly error: Error | null;
}

export type WebPaymentsErrorKind = 'invalid-argument' | 'not-configured' | 'auth-required' | 'context-changed' | 'disabled' | 'disposed' | 'busy' | 'attempt-required' | 'attempt-conflict' | 'checkout-uncertain' | 'checkout-unavailable' | 'timeout' | 'storage-unavailable' | 'storage-corrupt' | 'payment-failed' | 'synchronization-failed' | 'aborted';

/** Local orchestration errors; HTTP failures retain their original RestGoError. */
export class WebPaymentsError extends Error {
    readonly kind: WebPaymentsErrorKind;
    constructor(kind: WebPaymentsErrorKind, message: string);
}

/** Customer payment coordinator, owned by one page or reusable placement. */
export class WebPayments extends WebNonvisualComponent {
    #private;
    constructor(configuration?: WebPaymentsConfiguration);
    get gatewaySlug(): string;
    set gatewaySlug(value: string);
    get mode(): import("@webrad/restgo-sdk").RestGoPaymentMode;
    /** Changes only the default for a future prepared attempt. */
    set mode(value: import("@webrad/restgo-sdk").RestGoPaymentMode);
    get enabled(): boolean;
    set enabled(value: boolean);
    get pollInterval(): number;
    set pollInterval(value: number);
    get pollTimeout(): number;
    set pollTimeout(value: number);
    get busy(): boolean;
    get autoResume(): boolean;
    set autoResume(value: boolean);
    get autoWatch(): boolean;
    set autoWatch(value: boolean);
    get persistAttempts(): boolean;
    set persistAttempts(value: boolean);
    get state(): WebPaymentsState;
    get status(): string | null;
    get checkoutState(): string | null;
    get synchronizationPending(): boolean;
    get synchronizationError(): string | null;
    get canOpenCheckout(): boolean;
    get canCancelSubscription(): boolean;
    get history(): readonly import("@webrad/restgo-sdk").RestGoPaymentOperation[];
    get nextCursor(): string;
    get hasMore(): boolean;
    get watching(): boolean;
    get operation(): import("@webrad/restgo-sdk").RestGoPaymentOperation | null;
    get checkoutUrl(): string | null;
    get error(): Error | null;
    get attempt(): import("@webrad/restgo-sdk").RestGoCheckoutInput | null;
    /** Prepare/recover the purchase, persist its key, wait for checkout and open it. */
    Pay(sourceKey: string, options?: WebPaymentsCheckoutOptions): Promise<import("@webrad/restgo-sdk").RestGoPaymentOperation>;
    /** Subscribe through the hosted checkout with the same automatic recovery flow. */
    Subscribe(sourceKey: string, options?: WebPaymentsCheckoutOptions): Promise<import("@webrad/restgo-sdk").RestGoPaymentOperation>;
    /** Use the mode selected in the Inspector. Opens checkout by default. */
    Checkout(sourceKey: string, options?: WebPaymentsCheckoutOptions): Promise<import("@webrad/restgo-sdk").RestGoPaymentOperation>;
    /** Recover a purchase or the last saved attempt; never redirects back to checkout. */
    Resume(sourceKey?: string, options?: WebPaymentsResumeOptions): Promise<import("@webrad/restgo-sdk").RestGoPaymentOperation | null>;
    /** Refresh the selected/saved operation without creating a charge. */
    Refresh(options?: import("@webrad/restgo-sdk").RestGoPaymentRequestOptions): Promise<import("@webrad/restgo-sdk").RestGoPaymentOperation | null>;
    /** Load customer history and expose its cursor without changing selection. */
    LoadHistory(options?: import("@webrad/restgo-sdk").RestGoPaymentListOptions): Promise<readonly import("@webrad/restgo-sdk").RestGoPaymentOperation[]>;
    /** Append the next page, deduplicating operations. Last page is a harmless no-op. */
    LoadMore(options?: import("@webrad/restgo-sdk").RestGoPaymentRequestOptions): Promise<readonly import("@webrad/restgo-sdk").RestGoPaymentOperation[]>;
    /** Await payment success or subscription activation, optionally including source synchronization. */
    WaitForConfirmation(options?: WebPaymentsConfirmationOptions): Promise<import("@webrad/restgo-sdk").RestGoPaymentOperation>;
    /** Advanced preparation without HTTP. Default persistence saves its recovery checkpoint. */
    PrepareCheckout(sourceKey: string, mode?: import("@webrad/restgo-sdk").RestGoPaymentMode): WebPaymentsCheckpoint;
    CreateCheckout(options?: import("@webrad/restgo-sdk").RestGoPaymentRequestOptions): Promise<import("@webrad/restgo-sdk").RestGoPaymentOperation>;
    GetOperation(id: string, options?: import("@webrad/restgo-sdk").RestGoPaymentRequestOptions): Promise<import("@webrad/restgo-sdk").RestGoPaymentOperation>;
    ListOperations(options?: import("@webrad/restgo-sdk").RestGoPaymentListOptions): Promise<import("@webrad/restgo-sdk").RestGoPaymentOperationList>;
    CancelSubscription(options?: import("@webrad/restgo-sdk").RestGoPaymentRequestOptions): Promise<import("@webrad/restgo-sdk").RestGoPaymentOperation>;
    CancelSubscription(id: string, options?: import("@webrad/restgo-sdk").RestGoPaymentRequestOptions): Promise<import("@webrad/restgo-sdk").RestGoPaymentOperation>;
    WaitForCheckout(id?: string, options?: WebPaymentsObservationOptions): Promise<import("@webrad/restgo-sdk").RestGoPaymentOperation>;
    /** Starts one bounded loop. Background failures are delivered through OnError. */
    StartWatching(id?: string, options?: WebPaymentsObservationOptions): void;
    /** Local observation cancellation only; never cancels the backend transaction. */
    StopWatching(): void;
    OpenCheckout(): void;
    ExportCheckpoint(): WebPaymentsCheckpoint;
    /** Validates recovery data against this API, gateway and customer. Performs no HTTP. */
    RestoreCheckpoint(value: unknown): WebPaymentsCheckpoint;
    /** Save recovery data first. This only clears local state and never cancels a charge. */
    Clear(): void;
    set onCheckoutCreated(handler: WebComponentEventHandler<this> | null);
    set onCheckoutReady(handler: WebComponentEventHandler<this> | null);
    set onOperationChange(handler: WebComponentEventHandler<this> | null);
    set onSynchronizationChange(handler: WebComponentEventHandler<this> | null);
    set onError(handler: WebComponentEventHandler<this> | null);
    set onRequestComplete(handler: WebComponentEventHandler<this> | null);
    set onPaymentSucceeded(handler: WebComponentEventHandler<this> | null);
    set onSubscriptionActivated(handler: WebComponentEventHandler<this> | null);
    set onSubscriptionCanceled(handler: WebComponentEventHandler<this> | null);
    set onCheckoutOpened(handler: WebComponentEventHandler<this> | null);
    set onHistoryChange(handler: WebComponentEventHandler<this> | null);
    set onStateChange(handler: WebComponentEventHandler<this> | null);
    set onRestored(handler: WebComponentEventHandler<this> | null);
    dispose(): void;
}
